-- CHAMBA 051 — Al avanzar a completed, marcar completed_at en job_assignmentsCREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS worker_advance_operational_phase CASCADE;CREATE OR REPLACE FUNCTION worker_advance_operational_phase(  p_job_id UUID,  p_worker_id UUID,  p_phase TEXT)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_status job_status;  v_now TIMESTAMPTZ := NOW();BEGIN  IF p_phase NOT IN ('accepted', 'en_route', 'arrived', 'completed') THEN    RETURN jsonb_build_object('success', false, 'error', 'Fase inválida');  END IF;  IF NOT EXISTS (    SELECT 1 FROM job_assignments     WHERE job_id = p_job_id AND worker_id = p_worker_id  ) AND NOT EXISTS (    SELECT 1 FROM jobs     WHERE id = p_job_id AND assigned_worker_id = p_worker_id  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Sin asignación');  END IF;  v_status := CASE p_phase    WHEN 'completed' THEN 'completed'::job_status    WHEN 'arrived' THEN 'in_progress'::job_status    ELSE 'taken'::job_status  END;  UPDATE jobs     SET operational_phase = p_phase,         status = v_status,         updated_at = v_now   WHERE id = p_job_id;  IF p_phase = 'completed' THEN    UPDATE job_assignments       SET completed_at = v_now     WHERE job_id = p_job_id       AND worker_id = p_worker_id       AND completed_at IS NULL;  END IF;  RETURN jsonb_build_object('success', true, 'phase', p_phase, 'status', v_status::text);END;$$;GRANT EXECUTE ON FUNCTION worker_advance_operational_phase(UUID, UUID, TEXT)  TO anon, authenticated;NOTIFY pgrst, 'reload schema';